CREATE DATABASE `meridian_freight` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin; USE `meridian_freight`;
CREATE TABLE `clients` (id INT PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, city TEXT NOT NULL, joined_on DATE NOT NULL, status TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE `shipments` (id INT PRIMARY KEY, person_id INT NOT NULL, reference TEXT NOT NULL, amount_minor INT NOT NULL, status TEXT NOT NULL, destination TEXT NOT NULL, created_on DATE NOT NULL, note TEXT NULL, KEY(person_id)) ENGINE=InnoDB;
CREATE TABLE `shipment_items` (record_id INT NOT NULL, line_no INT NOT NULL, description TEXT NOT NULL, quantity INT NOT NULL, unit_minor INT NOT NULL, PRIMARY KEY(record_id,line_no)) ENGINE=InnoDB;
CREATE TABLE `invoices` (id INT PRIMARY KEY, record_id INT NOT NULL, amount_minor INT NOT NULL, channel TEXT NOT NULL, reference TEXT NOT NULL, booked_on DATE NOT NULL, KEY(record_id)) ENGINE=InnoDB;
CREATE TABLE `dispatchers` (id INT PRIMARY KEY, full_name TEXT NOT NULL, role TEXT NOT NULL, enabled INT NOT NULL, branch TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE access_notes (actor TEXT, action TEXT, source_ip TEXT, recorded_at DATETIME) ENGINE=InnoDB;
CREATE TABLE documents (id INT PRIMARY KEY, title VARCHAR(120), content BLOB, metadata JSON, amount DECIMAL(12,2), risk_score DOUBLE) ENGINE=InnoDB;
